mapper.select:
SELECT srm.SYS_ROLE_MODULE_ID , srm.ROLE_ID , srm.MODULE_CODE , sm.MODULE_NAME , srb.URL url, srm.SEQUENCE , srm.ENABLED_FLAG , (case when (select count(*) from sys_role_module_home_page srmw where srmw.module_code = sm.module_code and srmw.role_id = srm.role_id and srmw.subject = #{request.subject} ) > 0 then 'role_module' when (select count(*) from sys_module_home_page smhp where smhp.MODULE_CODE = sm.module_code and smhp.subject = #{request.subject}) > 0 then 'module' else 'none' end )module_Flag, (select count(*) from sys_role_module srm2,sys_function_b sfb where srm2.PARENT_MODULE_CODE = srm.MODULE_CODE and srm2.ROLE_ID = srm.ROLE_ID and sfb.MODULE_CODE = srm2.MODULE_CODE and not EXISTS (select * from sys_role_module_exclude_func srmef where srmef.ROLE_ID = srm.ROLE_ID and srmef.FUNCTION_ID = sfb.function_id) )function_Count, (select count(*) from sys_role_module srm2 where srm2.PARENT_MODULE_CODE = srm.MODULE_CODE and srm2.ROLE_ID = srm.ROLE_ID and srm2.enabled_flag = 'Y' )menu_Count FROM sys_role_module srm, sys_module sm LEFT JOIN sys_resource_b srb ON sm.HOMEPAGE_RESOURCE_ID = srb.REQUEST_ID WHERE srm.MODULE_CODE = sm.MODULE_CODE and sm.MODULE_CODE != 'UDEF'
and srm.ROLE_ID = #{roleId}
and (srm.parent_module_code is null or srm.parent_module_code = '') and srm.ENABLED_FLAG='Y' and sm.ENABLED_FLAG='Y' ORDER by srm.sequence asc

select * from (( SELECT sfb.function_id sys_role_module_id, srm.ROLE_ID role_id, sfb.FUNCTION_CODE module_code, srm.MODULE_CODE parent_module_code, (select sm.MODULE_NAME from sys_module sm where sm.MODULE_CODE = srm.MODULE_CODE) parent_module_name, sfb.FUNCTION_NAME module_name, (select srb.URL from sys_resource_b srb where srb.RESOURCE_ID = sfb.RESOURCE_ID) url, sfb.FUNCTION_SEQUENCE sequence, sfb.ENABLED_FLAG enabled_flag, 'function' module_flag, 0 sub_menu_count FROM sys_role_module srm, sys_function_b sfb where srm.MODULE_CODE = sfb.MODULE_CODE and srm.PARENT_MODULE_CODE is null and srm.ROLE_ID = #{roleId} and not EXISTS (select * from sys_role_module_exclude_func srmef where srmef.ROLE_ID = srm.ROLE_ID and srmef.FUNCTION_ID = sfb.function_id) ) union (SELECT srm.SYS_ROLE_MODULE_ID sys_role_module_id, srm.ROLE_ID role_id, srm.MODULE_CODE module_code, srm.PARENT_MODULE_CODE parent_module_code, 'MAIN' parent_module_name, sm.MODULE_NAME module_name, srb.URL url, srm.SEQUENCE sequence, srm.ENABLED_FLAG enabled_flag, (case when (select count(*) from sys_role_module_home_page srmw where srmw.module_code = sm.module_code and srmw.role_id = srm.role_id and srmw.subject = #{request.subject} ) > 0 then 'role_module' when (select count(*) from sys_module_home_page smhp where smhp.MODULE_CODE = sm.module_code and smhp.subject = #{request.subject}) > 0 then 'module' else 'none' end )module_flag, (select count(*) from sys_function_b sfb,sys_resource_b srb where sfb.MODULE_CODE = srm.MODULE_CODE and sfb.RESOURCE_ID = srb.RESOURCE_ID)sub_menu_count FROM sys_role_module srm, sys_module sm LEFT JOIN sys_resource_b srb ON sm.HOMEPAGE_RESOURCE_ID = srb.REQUEST_ID WHERE srm.MODULE_CODE = sm.MODULE_CODE
and srm.ROLE_ID = #{roleId}
and (srm.parent_module_code is not null) and srm.enabled_flag='Y' ))t order by t.sequence

SELECT srm.SYS_ROLE_MODULE_ID sysRoleModuleId, srm.ROLE_ID roleId, srm.MODULE_CODE moduleCode, sm.MODULE_NAME moduleName, srb.URL url, srm.sequence seq, srm.enabled_flag enabledFlag, srm.parent_module_code parentModuleCode FROM sys_role_module srm, sys_module sm LEFT JOIN sys_resource_b srb ON sm.HOMEPAGE_RESOURCE_ID = srb.RESOURCE_ID WHERE srm.MODULE_CODE = sm.MODULE_CODE
and srm.ROLE_ID = #{roleId}
and srm.MODULE_CODE = #{moduleCode}
order by seq asc
